{
  "attacks": [
    {
      "id": "C1",
      "claim": "A partial class marked [GeneratedMessagePackFormatter] that implements IMessagePackFormatter<T> for a type T from another assembly gets its Serialize and Deserialize members generated in the consuming project.",
      "outcome": "scenario_proposed",
      "scenario": "If the type T is an inaccessible type (e.g., an `internal` type from another assembly), the generator will reject it and report MsgPack021 instead of generating the members.",
      "test_sketch": "Declare an `internal class InternalType` in Project A. In Project B, declare `[GeneratedMessagePackFormatter] partial class Formatter : IMessagePackFormatter<InternalType>`. The generator will emit MsgPack021 and not generate the members.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 66,
          "quote": "|| !compilation.IsSymbolAccessibleWithin(type, formatter))"
        }
      ]
    },
    {
      "id": "C2",
      "claim": "Without a surrogate, the generated formatter writes every public read-write instance property and field of T as a string-keyed map entry named after the member.",
      "outcome": "scenario_proposed",
      "scenario": "If the type T has a public read-write indexer property, it is explicitly skipped and not written as a map entry.",
      "test_sketch": "Define `class T { public int this[int key] { get => 0; set { } } }`. Generate a formatter without a surrogate. The indexer is not serialized.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 262,
          "quote": "if (member is IPropertySymbol { IsIndexer: true })"
        },
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 264,
          "quote": "continue;"
        }
      ]
    },
    {
      "id": "C3",
      "claim": "Attributes that are present on T are used for the wire contract.",
      "outcome": "scenario_proposed",
      "scenario": "Attributes on T are completely ignored by the generator when using `[GeneratedMessagePackFormatter]`. For example, a property marked with `[IgnoreMember]` on T will still be serialized.",
      "test_sketch": "Define `class T { [IgnoreMember] public int X { get; set; } }`. Generate a formatter for T without a surrogate. The property `X` is serialized, proving the attribute on T was ignored.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 133,
          "quote": "List<ISymbol> targets = GetInstanceMembers(type).Where(IsPublicReadWrite).OrderBy(m => m.Name, StringComparer.Ordinal).ToList();"
        }
      ]
    },
    {
      "id": "C4",
      "claim": "The generated resolver registers each generated formatter, so GeneratedMessagePackResolver.Instance returns it for the formatted type.",
      "outcome": "could_not_falsify",
      "scenario": "",
      "test_sketch": "",
      "citations": []
    },
    {
      "id": "C5",
      "claim": "The fixture assembly that declares the formatted types has no MessagePack reference, so the feature works without adding anything to the assembly that owns T.",
      "outcome": "could_not_falsify",
      "scenario": "",
      "test_sketch": "",
      "citations": []
    },
    {
      "id": "C6",
      "claim": "Hand-written formatters and existing generated formatters are unaffected: the exclusion in the formatter search only matches classes carrying the new attribute, and the template keeps 'internal sealed class' for every other formatter.",
      "outcome": "could_not_falsify",
      "scenario": "",
      "test_sketch": "",
      "citations": []
    },
    {
      "id": "C7",
      "claim": "The new attribute, the four analyzer diagnostics and the surrogate option are documented in the README, in per-diagnostic pages and in the analyzer release notes.",
      "outcome": "could_not_falsify",
      "scenario": "",
      "test_sketch": "",
      "citations": []
    },
    {
      "id": "C8",
      "claim": "Only public read-write members are written. Read-only members and members with a non-public setter are skipped, and no diagnostic says so.",
      "outcome": "scenario_proposed",
      "scenario": "If a surrogate type is used and it includes a member that matches a read-only member on the formatted type, the generator reports a diagnostic (MsgPack022).",
      "test_sketch": "Define `class T { public int ReadOnlyProp { get; } }` and a surrogate `class Surrogate { [Key(0)] public int ReadOnlyProp { get; set; } }`. The generator will emit MsgPack022.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 190,
          "quote": "if (target is null || !IsPublicReadWrite(target) || !SymbolEqualityComparer.Default.Equals(GetMemberType(target), GetMemberType(surrogateMember)))"
        },
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 193,
          "quote": "MsgPack00xMessagePackAnalyzer.SurrogateMemberNotFound,"
        }
      ]
    },
    {
      "id": "C9",
      "claim": "Misuse of the attribute is reported as a compile error: a non-partial formatter (MsgPack019), a class that does not implement IMessagePackFormatter<T> (MsgPack020), an abstract type (MsgPack021) and surrogate mismatches (MsgPack022, MsgPack005).",
      "outcome": "could_not_falsify",
      "scenario": "",
      "test_sketch": "",
      "citations": []
    },
    {
      "id": "C10",
      "claim": "A surrogate type's [Key] and [IgnoreMember] attributes decide which members are written and under which keys, with members matched by name and type.",
      "outcome": "scenario_proposed",
      "scenario": "The matching only checks name and type, not member kind. A field in the surrogate can successfully match a property in the formatted type.",
      "test_sketch": "Define `class T { public int Id { get; set; } }` and a surrogate `class Surrogate { [Key(0)] public int Id; }`. The generator accepts this and serializes the property.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 189,
          "quote": "ISymbol? target = targetMembers.FirstOrDefault(m => m.Name == surrogateMember.Name);"
        },
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 190,
          "quote": "if (target is null || !IsPublicReadWrite(target) || !SymbolEqualityComparer.Default.Equals(GetMemberType(target), GetMemberType(surrogateMember)))"
        }
      ]
    },
    {
      "id": "C11",
      "claim": "Adding the public attribute class GeneratedMessagePackFormatterAttribute to the MessagePack.Annotations assembly is additive and does not change existing public API.",
      "outcome": "could_not_falsify",
      "scenario": "",
      "test_sketch": "",
      "citations": []
    },
    {
      "id": "NEW1",
      "claim": "Custom formatters specified on surrogate members are ignored.",
      "outcome": "new_hypothesis",
      "scenario": "If a surrogate member is annotated with `[MessagePackFormatter]`, the generator ignores it and does not apply the custom formatter to the serialized member.",
      "test_sketch": "Define a surrogate with `[Key(0), MessagePackFormatter(typeof(CustomIntFormatter))] public int Id { get; set; }`. The generated formatter will use the default int formatter, not `CustomIntFormatter`.",
      "citations": [
        {
          "path": "src/MessagePack.SourceGenerator/CodeAnalysis/GeneratedFormatterCollector.cs",
          "line": 238,
          "quote": "CustomFormatter: null)"
        }
      ]
    }
  ]
}
